cd multicode/obelisk/full; python3 - <<'E'
p='core/statues.mjs'
s=open(p).read()
s=s.replace("// Правило 15:","// Правила 21–25 (версия 4, этап 8.46): постройка наборов W1/W3/W4 — unlocked, lockedText, offerSet, canBuySet, buildSet (таблицы sets, costs, costs2, locked, locked2, unlock, tiers, statues, statues2).\n// Правило 15:",1)
new='''  // правила 21–25: постройка наборов 1 (W1), 2 (W3), 3 (W4)
  const setRow = (set) => T.sets.find((r) => r.set === set);

  // правило 22
  function unlocked(set, tier, world, obelisk) {
    if (tier >= setRow(set).tiers) return false;
    const u = T.unlock.find((r) => r.set === set && r.tier === tier);
    return u !== undefined && world >= u.world && obelisk >= u.obelisk;
  }

  // правило 23
  function lockedTextSet(set, tier) {
    const r = set === 1
      ? T.locked.find((x) => x.tier === tier)
      : T.locked2.find((x) => x.set === set && x.tier === tier);
    return r ? r.text : null;
  }

  // правило 24
  function priceSet(set, levels, tier) {
    let n = 0;
    for (const l of levels) if (l > tier) n++;
    const rows = set === 1
      ? T.costs.filter((r) => r.tier === tier && r.k === n)
      : T.costs2.filter((r) => r.set === set && r.tier === tier && r.k === n);
    return { k: n, items: rows.sort((a, b) => a.item - b.item).map((r) => ({ type: r.type, id: r.id, cost: r.cost })) };
  }

  function stockSet(state, it) {
    if (it.type === 'bar') return state.bars[it.id];
    if (it.type === 'vein') return state.veins[it.id];
    if (it.type === 'star') return state.stars[it.id];
    return state.gems;
  }

  function offerSet(set, state) {
    const levels = state.levels[set - 1];
    const tier = Math.min(...levels);
    if (!unlocked(set, tier, state.world, state.obelisk)) return { tier, locked: lockedTextSet(set, tier) };
    const p = priceSet(set, levels, tier);
    const candidates = [];
    levels.forEach((l, i) => { if (l === tier) candidates.push(i); });
    return { tier, k: p.k, items: p.items, candidates };
  }

  function canBuySet(set, state) {
    const o = offerSet(set, state);
    if (o.locked !== undefined) return false;
    return o.items.every((it) => stockSet(state, it) - it.cost >= -k['afford.eps']);
  }

  // правило 25
  function buildSet(set, state, rng) {
    const copy = {
      ...state,
      levels: state.levels.map((l) => [...l]),
      bars: [...state.bars],
      veins: [...state.veins],
      stars: state.stars && [...state.stars],
    };
    if (!canBuySet(set, state)) return { state: copy, built: false, pick: -1, events: [] };
    const o = offerSet(set, state);
    let gems = 0;
    for (const it of o.items) {
      if (it.type === 'bar') copy.bars[it.id] = copy.bars[it.id] - it.cost;
      else if (it.type === 'vein') copy.veins[it.id] = copy.veins[it.id] - it.cost;
      else if (it.type === 'star') copy.stars[it.id] = copy.stars[it.id] - it.cost;
      else { copy.gems = copy.gems - it.cost; gems = gems + it.cost; }
    }
    copy.gemsSpent = copy.gemsSpent + gems;
    const pick = roll(copy.levels[set - 1], rng);
    copy.levels[set - 1][pick] = o.tier + 1;
    const name = set === 1
      ? T.statues[pick].name
      : T.statues2.find((r) => r.set === set && r.statue === pick).name;
    const events = [
      { group: k['log.gems.group'], text: format(k['log.gems'], { gems: Math.trunc(gems) }) },
      { group: k['log.built.group'], text: format(k['log.builtSet'], { prefix: tierPrefix(o.tier + 1), name, set: setRow(set).id }) },
    ];
    return { state: copy, built: true, pick, events };
  }

  return { offer, canBuy, openMenu, press, close, buttonAt, externals, rules, roll, rollFor, unlocked, lockedText: lockedTextSet, offerSet, canBuySet, buildSet };
}
'''
i=s.rindex("  return { offer")
s=s[:i]+new
open(p,'w').write(s)
E
